  "aliases": [
    "IPM"
  ]
}

{
  "id": "model_equation",
  "label": "模型方程",
  "gloss": "为研究爆破机制而改写的玩具方程,如平均化 NS、二进级联模型"
}

{
  "id": "navier_stokes_equations",
  "label": "Navier–Stokes 方程",
  "gloss": "带粘性的不可压流体方程 ∂_t u + u·∇u = νΔu − ∇p + f,div u = 0;Clay 千禧年问题的对象",
  "aliases": [
    "纳维–斯托克斯方程",
    "NS"
  ],
  "basis": "Fefferman 官方问题陈述"
}

{
  "id": "forced_navier_stokes",
  "label": "带外力的 Navier–Stokes",
