}

{
  "id": "mathematical_result",
  "label": "数学结果",
  "gloss": "一条已证明或被宣称证明的定理、构造或障碍"
}

{
  "id": "blowup_result",
  "label": "爆破结果",
  "gloss": "构造出光滑解在有限时间失去光滑(某范数发散)的结果",
  "aliases": [
    "finite-time singularity"
  ]
}

{
  "id": "forced_blowup_result",
  "label": "强迫爆破结果",
  "gloss": "借助专门设计的光滑外力实现的有限时间爆破"
}

{
  "id": "regularity_result",
  "label": "正则性结果",
  "gloss": "证明解保持光滑或奇异集受控的结果"
}

{
  "id": "obstruction_result",
  "label": "障碍结果",
  "gloss": "证明某类方法或构造不能达成某目标的结果"
}

{
  "id": "nonuniqueness_result",
  "label": "非唯一性结果",
  "gloss": "构造同一初值(与外力)下多个弱解的结果"
}

